  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Apomorphine, a close aporphine analogue, readily crossed the BBB in rats with brain concentrations exceeding plasma levels after systemic dosing, supporting CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Mianserin, a structurally related N-methyl tetracyclic amine, showed a logBB of 0.99 in rats, indicating good brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "S(+)-Apomorphine showed a brain-to-plasma AUC ratio of 228% in mice, directly demonstrating substantial CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Nuciferine, a related aporphine alkaloid, reached brain concentrations almost equal to plasma in rats, confirming BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Berberrubine, a berberine-type alkaloid, was detected in rat CSF after systemic administration, demonstrating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "N-Propylnorapomorphine showed good brain penetration in rats and nonhuman primates by ex vivo dissection and PET imaging.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a methylenedioxy-containing N-methyl isoquinoline/benzazepine alkaloid closely related to protopine/berberine-type CNS-active alkaloids. Multiple highly transferable experimental records consistently demonstrate BBB penetration via brain/plasma ratios, CSF detection, PET imaging, and brain tissue measurements. Therefore meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct pharmacokinetic or CSF measurement is available for the exact query molecule, so prediction relies on close structural analogues.",
    "Efflux liability was not explicitly quantified for the query, but several analogues show net brain exposure despite potential transporter interactions."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

